const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function isThief(a){return thiefIds.has(a.id)}
function initLagos(){cashDrops=[];messes=[];trap=null;bribeOffer=null;lureOffer=null;streetClock=0;meetingPositions=null;for(const a of actors){a.wallet=300;a.lureUsed=false;a.killCD=22;a.mischiefCD=10;a.bribedBy=new Set();a.gasEscape=0}for(const r of level.rooms){const clear=r.tiles.filter(([x,z])=>grid[z]?.[x]===0);for(let i=0;i<2;i++){const t=clear[(r.id*11+i*13)%clear.length];cashDrops.push({...center(...t),amount:i?100:50})}}}
function updateLagosHUD(){if(!player)return;$('#wallet').textContent='₦'+player.wallet;$('#street').textContent=bribeOffer?'Anonymous offer':lureOffer?'Money call':'Lagos';$('#escape-gas').hidden=!(trap?.target===0&&state==='playing');$('#gas-alert').hidden=!(trap?.target===0&&state==='playing');if(trap?.target===0){$('#gas-alert').textContent='Gutter gas! '+Math.ceil(trap.left)+'s · Break the lock '+trap.escape+'/5';}}
function addChat(id,text,kind='chat'){if(!meetingSession)return;const a=actors[id];const row=document.createElement('p');row.className='chat-row';const name=document.createElement('strong');name.textContent=(id===0?'You':a.name)+(kind==='case'?' · case':'')+': ';row.append(name,document.createTextNode(text));$('#group-chat').append(row);while($('#group-chat').children.length>70)$('#group-chat').firstChild.remove();$('#group-chat').scrollTop=$('#group-chat').scrollHeight;meetingSession.chat.push({id,text,kind});}
function castVote(choice){if(state!=='meeting'||!meetingSession)return;meetingSession.choice=choice;modal.querySelectorAll('[data-vote]').forEach(b=>{b.classList.toggle('selected-vote',+b.dataset.vote===choice);b.setAttribute('aria-pressed',+b.dataset.vote===choice)});$('#skip-vote').classList.toggle('selected-vote',choice===-1);$('#meeting-update').textContent='Vote saved: '+(choice<0?'skip':actors[choice].name)+'. You can change it until the countdown ends.';}
function beginMeeting(body,announcement){if(state!=='playing')return;$('#notice').hidden=true;meetingBody=body;bodies.forEach(b=>b.reported=true);trap=null;pendingMachine=null;route=[];blackout=0;meetingPositions=actors.map(a=>({id:a.id,x:a.x,z:a.z}));const r=level.rooms[4],seats=r.tiles.filter(([x,z])=>safe(x+.5,z+.5));actors.filter(a=>a.alive).forEach((a,i)=>{const t=seats[Math.floor((i+.5)*seats.length/actors.filter(a=>a.alive).length)];Object.assign(a,center(...t));a.route=[]});const alive=actors.filter(a=>a.alive);showDialog(`<div class="meeting-clock"><span id="meeting-phase">Make your case if you no be thief</span><strong id="meeting-countdown" role="timer">5s</strong></div><h2 id="modal-title">Common-room palaver</h2><p class="hint">${escapeHTML(announcement)} · Solo bot test</p><div id="speaker-banner" role="status"></div><div id="group-chat" role="log" aria-label="Group conversation" aria-live="polite"></div><form id="chat-form"><label for="chat-input">Group chat — everyone can talk</label><div class="chat-compose"><input id="chat-input" maxlength="180" autocomplete="off" placeholder="Who you suspect? Make your case…"><button type="submit" class="primary">Send</button></div></form><details id="vote-panel"><summary>Vote / change vote</summary><div class="suspects">${alive.map(a=>`<button class="suspect" data-vote="${a.id}" aria-pressed="false"><span class="swatch" style="background:${a.color}"></span>${escapeHTML(a.name)}${a.id===0?' (you)':''}</button>`).join('')}</div><button id="skip-vote">Skip vote</button></details><p id="meeting-update" class="hint" role="status">Votes stay open during the conversation and final voting window.</p>`,'meeting');modal.classList.add('palaver');meetingSession={phase:'cases',order:shuffle(alive.map(a=>a.id)),turn:0,deadline:performance.now()+5000,choice:null,extended:false,body,chat:[],botVotes:new Map(),nextChat:performance.now()+2500};$('#chat-form').onsubmit=e=>{e.preventDefault();const text=$('#chat-input').value.trim();if(!text||!meetingSession)return;addChat(0,text,meetingSession.phase==='cases'&&meetingSession.order[meetingSession.turn]===0?'case':'chat');$('#chat-input').value='';};modal.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>castVote(+b.dataset.vote));$('#skip-vote').onclick=()=>castVote(-1);announceSpeaker();render();}
function botCase(a){const b=meetingSession.body;if(b?.witnesses.includes(a.id)&&!isThief(a)&&!a.bribedBy.has(b.killer))return {text:'I saw '+actors[b.killer].name+' do it. No be guess.',vote:b.killer};if(b&&isThief(a)){const target=actors.find(x=>x.alive&&!isThief(x)&&x.id!==a.id);return {text:target?'I saw '+target.name+' near that side. Ask them.':'I was minding my business.',vote:target?.id??-1}}if(b?.witnesses.includes(a.id)&&a.bribedBy.has(b.killer))return {text:'I no get clear evidence. I pass.',vote:-1};return {text:['No hard evidence from me. Make we no rush.','I was looking for money and doing my task.','Who was in that room? Talk your own.'][a.id%3],vote:-1};}
function announceSpeaker(){const m=meetingSession;if(!m)return;const id=m.order[m.turn];$('#speaker-banner').textContent=id===0?'YOUR TURN — Make your case if you no be thief!':actors[id].name+' gets 5 seconds to make their case.';$('#speaker-banner').classList.toggle('your-turn',id===0);if(id!==0){const c=botCase(actors[id]);m.botVotes.set(id,c.vote);addChat(id,c.text,'case');}else $('#chat-input').focus({preventScroll:true});}
function meetingTally(){const m=meetingSession,counts={};for(const a of actors.filter(a=>a.alive)){const v=a.id===0?(m.choice??-1):(m.botVotes.get(a.id)??-1);counts[v]=(counts[v]||0)+1}const ranking=Object.entries(counts).sort((a,b)=>b[1]-a[1]);const tie=ranking.length>1&&ranking[0][1]===ranking[1][1];return {counts,tie,out:!tie&&Number(ranking[0][0])>=0?Number(ranking[0][0]):-1};}
function meetingTick(now){if(state!=='meeting'||!meetingSession)return;const m=meetingSession;if(now>=m.nextChat){const a=actors.filter(a=>a.alive&&a.id!==0)[Math.floor(Math.random()*actors.filter(a=>a.alive&&a.id!==0).length)];if(a)addChat(a.id,['Evidence first, abeg.','I dey hear everybody.','That free money story sef suspicious.'][Math.floor(Math.random()*3)]);m.nextChat=now+6500}if(now>=m.deadline){if(m.phase==='cases'){m.turn++;if(m.turn<m.order.length){m.deadline=now+5000;announceSpeaker()}else{m.phase='vote';m.deadline=now+30000;$('#meeting-phase').textContent='Decide together · final vote';$('#speaker-banner').textContent='Everyone has had a turn. Group chat stays open.';$('#vote-panel').open=true;for(const a of actors.filter(a=>a.alive&&a.id!==0&&!isThief(a))){const b=m.body;const witnesses=b?b.witnesses.filter(id=>actors[id].alive&&!isThief(actors[id])&&!actors[id].bribedBy.has(b.killer)):[];if(witnesses.length)m.botVotes.set(a.id,b.killer);else if((m.botVotes.get(a.id)??-1)===-1&&Number.isInteger(m.choice)&&m.choice>=0&&m.chat.some(c=>c.id===0&&c.text.toLowerCase().includes(actors[m.choice].name.toLowerCase()))&&a.id%3===0)m.botVotes.set(a.id,m.choice)}}}else{const tally=meetingTally();if(tally.tie&&!m.extended){m.extended=true;m.deadline=now+10000;$('#meeting-phase').textContent='Tiebreaker · chat stays open';$('#speaker-banner').textContent='Stalemate. 10 more seconds to decide.';}else{resolveMeeting(tally);return}}}$('#meeting-countdown').textContent=Math.max(0,Math.ceil((m.deadline-now)/1000))+'s';}
function restoreMeeting(){if(meetingPositions){for(const p of meetingPositions)Object.assign(actors[p.id],{x:p.x,z:p.z});meetingPositions=null}modal.classList.remove('palaver');}
function resolveMeeting({counts,tie,out}){meetingSession=null;modal.close();if(out>=0){actors[out].alive=false;actors[out].route=[];notes.push(actors[out].name+' was ejected. '+(isThief(actors[out])?'They were a thief.':'They were crew.'))}const tally=Object.entries(counts).map(([id,n])=>(id==='-1'?'Skip':actors[+id].name)+': '+n).join(' · ');showDialog(`<p class="eyebrow">Palaver result</p><h2 id="modal-title">${out<0?'Nobody was ejected.':escapeHTML(actors[out].name)+' was ejected.'}</h2><p>${escapeHTML(tally)}</p><p>${out<0?(tie?'Still tied. Nobody goes out.':'The group skipped.'):(isThief(actors[out])?'One thief caught.':'They were crew.')}</p><div class="dialog-actions"><button id="vote-continue" class="primary">Return to the compound</button></div>`,'vote-result');$('#vote-continue').onclick=()=>{restoreMeeting();resume();if(out===0)finish(false,'You were ejected by the group.');else checkWin();killCooldown=Math.max(6,killCooldown);updateUI()};}
function lure(a,real){if(a.lureUsed||a.wallet<(real?100:0))return false;const r=roomAt(a);if(!r){if(a.id===0)notice('Enter a room to make your money call.');return false}a.lureUsed=true;if(real){a.wallet-=100;cashDrops.push({x:a.x,z:a.z,amount:100,lureOwner:a.id})}const choices=actors.filter(v=>v.alive&&v.id!==a.id&&!(isThief(a)&&isThief(v)));const target=choices.sort((v,w)=>distance(a,v)-distance(a,w))[0];if(target){target.route=path(target,a);target.lureDestination={x:a.x,z:a.z};target.lureSeconds=18;if(target.id===0){lureOffer={from:a.id,x:a.x,z:a.z,room:r.name};}}const msg=a.name+' says: “₦100 dey '+r.name+'! Come check.” True or one chance?';notes.push(msg);notice(msg);return true;}
function bribe(killer,target){const proof=bodies.some(b=>b.killer===killer.id&&b.witnesses.includes(target.id));if(!isThief(killer)||!target.alive||isThief(target)||!proof||killer.wallet<100||target.bribedBy.has(killer.id)||bribeOffer?.from===killer.id&&bribeOffer?.to===target.id)return false;if(target.id===0){bribeOffer={from:killer.id,to:0,amount:100};notice('Anonymous offer: ₦100 to keep quiet. Open Lagos to accept or reject.');return true}killer.wallet-=100;target.wallet+=100;const accepted=Math.random()<.65;if(accepted)target.bribedBy.add(killer.id);if(killer.id===0)notice(accepted?'Anonymous bribe delivered. The witness accepted silence.':'The witness took the money but refused silence.');return true;}
function respondBribe(accept){const offer=bribeOffer;if(!offer)return;if(accept&&actors[offer.from].wallet>=offer.amount){actors[offer.from].wallet-=offer.amount;player.wallet+=offer.amount;player.bribedBy.add(offer.from);notes.push('You accepted an anonymous ₦100 offer. You can still choose to expose the thief.');}bribeOffer=null;resume();notice(accept?'₦100 received. Your vote and chat are still your choice.':'Offer rejected.');}
function evilAction(a,kind){if(!isThief(a)||a.mischiefCD>0)return false;const r=roomAt(a);if(!r||kind==='clog'&&r.id!==3||messes.some(m=>m.roomId===r.id&&m.kind===kind)){if(a.id===0)notice(kind==='clog'?'Go to the Washroom to clog a toilet.':'Already done in this room.');return false}const toilet=kind==='clog'?level.props.filter(p=>p.roomId===r.id&&p.kind==='medical').sort((p,q)=>distance(a,{x:p.x+p.w/2,z:p.z+p.h/2})-distance(a,{x:q.x+q.w/2,z:q.z+q.h/2}))[0]:null;messes.push({x:toilet?toilet.x+toilet.w/2:a.x,z:toilet?toilet.z+toilet.h/2+.7:a.z,roomId:r.id,kind,toilet});a.mischiefCD=12;if(kind==='clog'){remaining=Math.max(1,remaining-8)}if(a.id===0)notice({pee:'Puddle left. Anyone crossing it slows down.',graffiti:'Wall tagged. Your mark stays in the room.',litter:'Rubbish dumped. Crew can clean it up.',clog:'Toilet blocked! Dirty water floods the washroom. −8s.'}[kind]);return true;}
function lockRoom(a){if(!isThief(a)||trap||a.mischiefCD>0)return false;const r=roomAt(a);if(!r)return false;const targets=actors.filter(v=>v.alive&&v.id!==a.id&&roomAt(v)?.id===r.id);if(targets.length!==1||isThief(targets[0])){if(a.id===0)notice('The room must contain exactly one other person, and they must be crew.');return false}const target=targets[0];const exit=level.corridors.flatMap(([x,z,w,h])=>{const out=[];for(let j=z;j<z+h;j++)for(let i=x;i<x+w;i++)if(safe(i+.5,j+.5)&&!roomAt(center(i,j)))out.push(center(i,j));return out}).map(p=>({p,route:path(a,p)})).filter(q=>q.route.length).sort((v,w)=>v.route.length-w.route.length)[0];if(!exit)return false;Object.assign(a,exit.p);a.route=[];if(a.id===0)route=[];trap={roomId:r.id,target:target.id,killer:a.id,left:8,escape:0};target.route=[];a.mischiefCD=45;if(target.id===0)notice('The room is locked! Gutter gas in 8 seconds — press Escape gas 5 times.');else if(a.id===0)notice('One person locked in. They can break free before the gas takes them.');return true;}
function escapeGas(){if(trap?.target!==0||state!=='playing')return;trap.escape++;if(trap.escape>=5){trap=null;notice('Lock broken. You escaped the gutter gas.')}updateLagosHUD();}
function streetMenu(){if(state!=='playing')return;const r=roomAt(player),witnesses=actors.filter(a=>a.alive&&!isThief(a)&&a.id!==0&&bodies.some(b=>b.killer===0&&b.witnesses.includes(a.id)));showDialog(`<p class="eyebrow">Lagos Life · test sandbox</p><h2 id="modal-title">Street moves</h2><p>Wallet: <strong>₦${player.wallet}</strong> · ${r?escapeHTML(r.name):'Corridor'}</p>${lureOffer?`<div class="street-section"><h3>Money call from ${escapeHTML(actors[lureOffer.from].name)}</h3><p>They claim ₦100 is in ${escapeHTML(lureOffer.room)}. It could be true or one chance.</p><button id="take-chance">Take my chances</button> <button id="ignore-lure">Ignore</button></div>`:''}${bribeOffer?'<div class="street-section"><h3>Anonymous offer</h3><p>Someone offers ₦100 for your silence. Their identity is hidden. You can still speak or vote freely.</p><button id="bribe-yes">Accept ₦100</button> <button id="bribe-no">Reject</button></div>':''}<div class="street-section"><h3>Money call · once per round</h3><p class="hint">Anyone can call people over. Real costs ₦100; fake pays nothing. Others must take their chances.</p><div class="street-grid"><button id="lure-real" ${player.lureUsed||player.wallet<100?'disabled':''}>Real ₦100 lure</button><button id="lure-fake" ${player.lureUsed?'disabled':''}>Fake money lure</button></div></div>${role==='thief'?`<div class="street-section"><h3>Evil tasks · ${Math.ceil(player.mischiefCD)}s cooldown</h3><div class="street-grid">${[['pee','Pee on floor'],['graffiti','Graffiti wall'],['litter','Drop litter'],['clog','Clog toilet']].map(([kind,label])=>`<button data-evil="${kind}" ${player.mischiefCD>0||!r||kind==='clog'&&r.id!==3?'disabled':''}>${label}</button>`).join('')}<button id="lock-room" ${player.mischiefCD>0||trap?'disabled':''}>Lock one person + gas</button></div><p class="hint">8s trap. Exactly one crew target. They can break the lock; meetings release it.</p></div><div class="street-section"><h3>Anonymous bribe · ₦100</h3><p class="hint">Only actual witnesses to your elimination can receive an offer. Acceptance does not guarantee loyalty.</p>${witnesses.length?witnesses.map(a=>`<button data-bribe="${a.id}" ${player.wallet<100||a.bribedBy.has(0)?'disabled':''}>Offer ${escapeHTML(a.name)} ₦100</button>`).join(''):'<p class="hint">No eligible witness right now.</p>'}</div>`:''}<div class="street-section"><button id="clean-mess" ${!r||!messes.some(m=>m.roomId===r.id)?'disabled':''}>Clean this room · earn ₦50</button></div><div class="dialog-actions"><button id="street-back">Back to the round</button></div>`,'street');$('#street-back').onclick=resume;if($('#take-chance')){$('#take-chance').onclick=()=>{const offer=lureOffer;lureOffer=null;resume();route=path(player,offer);notice('Taking your chances. Follow the route and watch your back.')};$('#ignore-lure').onclick=()=>{lureOffer=null;resume();notice('Money call ignored.')}}$('#lure-real').onclick=()=>{resume();lure(player,true);updateUI()};$('#lure-fake').onclick=()=>{resume();lure(player,false);updateUI()};modal.querySelectorAll('[data-evil]').forEach(b=>b.onclick=()=>{resume();evilAction(player,b.dataset.evil);updateUI()});if($('#lock-room'))$('#lock-room').onclick=()=>{resume();lockRoom(player);updateUI()};modal.querySelectorAll('[data-bribe]').forEach(b=>b.onclick=()=>{resume();bribe(player,actors[+b.dataset.bribe]);updateUI()});if($('#bribe-yes')){$('#bribe-yes').onclick=()=>respondBribe(true);$('#bribe-no').onclick=()=>respondBribe(false)}$('#clean-mess').onclick=()=>{messes=messes.filter(m=>m.roomId!==r.id);player.wallet+=50;resume();notice('Room cleaned. ₦50 earned.');updateUI()};}
function lagosTick(dt){streetClock+=dt;for(const a of actors.filter(a=>a.alive)){a.killCD=Math.max(0,(a.killCD||0)-dt);a.mischiefCD=Math.max(0,a.mischiefCD-dt);a.speed=(a.id===0?3.7:1.5+levelIndex*.06)*(messes.some(m=>(m.kind==='pee'||m.kind==='clog')&&m.roomId===roomAt(a)?.id&&distance(a,m)<1.3)?.55:1);for(let i=cashDrops.length-1;i>=0;i--){const c=cashDrops[i];if(distance(a,c)<.65&&c.lureOwner!==a.id){a.wallet+=c.amount;cashDrops.splice(i,1);if(a.id===0)notice('Picked up ₦'+c.amount+'.')}}if(a.lureSeconds>0){a.lureSeconds-=dt;if(a.id!==0&&a.lureDestination&&distance(a,a.lureDestination)>.5&&!a.route.length)a.route=path(a,a.lureDestination)}if(a.id!==0&&isThief(a)){const witness=actors.find(v=>v.alive&&!isThief(v)&&bodies.some(b=>b.killer===a.id&&b.witnesses.includes(v.id))&&!v.bribedBy.has(a.id)&&!bodies.some(b=>b.killer===a.id&&b.bribeAttempted));if(witness){bribe(a,witness);bodies.filter(b=>b.killer===a.id).forEach(b=>b.bribeAttempted=true)}}}if(trap){trap.left-=dt;if(trap.target!==0&&Math.random()<dt*.42){trap.escape++;if(trap.escape>=5){trap=null;return}}if(trap.left<=0){const t=trap;trap=null;eliminate(actors[t.killer],actors[t.target]);}}if(streetClock>28){streetClock=0;const a=actors[1+Math.floor(Math.random()*9)];if(a?.alive){if(!a.lureUsed&&roomAt(a))lure(a,Math.random()<.5);else if(isThief(a)){if(Math.random()<.3)lockRoom(a);else evilAction(a,['pee','litter','graffiti','clog'][Math.floor(Math.random()*4)]);}}}}
function renderLagos(near){for(const c of cashDrops)if(near(c.x,c.z)&&roomAt(player)?.id===roomAt(c)?.id){box(c.x,.11,c.z,.42,.06,.24,'#72bc8f',.25);box(c.x,.146,c.z,.09,.014,.24,'#f1df9a',.25);}for(const m of messes){if(roomAt(player)?.id!==m.roomId)continue;const r=level.rooms[m.roomId];if(m.kind==='pee'||m.kind==='clog'){ball(m.x,.058,m.z,m.kind==='clog'?1.5:.85,.012,m.kind==='clog'?1.4:.64,m.kind==='clog'?'#627855':'#c5a757');if(m.kind==='clog'&&m.toilet){const q=m.toilet;cylinder(q.x+q.w/2,.663,q.z+q.h/2,.4,.025,.48,'#627855');}}else if(m.kind==='litter'){for(let i=0;i<7;i++)box(m.x+Math.sin(i*2)*.65,.09,m.z+Math.cos(i*2)*.6,.2,.06,.3,i%2?'#d3c6a0':'#a86850',i*.9);}else if(m.kind==='graffiti'){const x=r.x+r.w/2,z=r.z+.09;for(let i=0;i<5;i++)box(x+(i-2)*.23,1.0+(i%2)*.15,z,.13,.48,.08,'#e56458',i%2?.4:-.4);}}if(trap&&roomAt(player)?.id===trap.roomId){const r=level.rooms[trap.roomId];for(const [x,z] of r.tiles)for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){if(grid[z+dz]?.[x+dx]===0&&!r.tileSet.has((x+dx)+','+(z+dz))){const bx=x+.5+dx*.5,bz=z+.5+dz*.5;box(bx,.8,bz,dx?.09:1,1.6,dz?.09:1,'#c5a757');glowBox(bx,1.55,bz,dx?.12:1,.08,dz?.12:1,'#e56458')}}for(let i=0;i<8;i++)ball(r.x+1+(i*2)%Math.max(1,r.w-2),.4+(i%3)*.27,r.z+1+(i*3)%Math.max(1,r.h-2),.7,.4,.7,'#7b9855',0,0,.35);}}
$('#street').onclick=streetMenu;$('#escape-gas').onclick=escapeGas;

function frame(now){let dt=Math.min((now-last)/1000||0,.04);last=now;meetingTick(now);tick(dt);render();requestAnimationFrame(frame)}renderStages();requestAnimationFrame(frame);